function vaporPressure(T){
  T=+T; if(isNaN(T)) return {error:'请输入温度（°C）'};
  if(T<-50||T>300) return {error:'温度范围建议 -50~300°C'};
  var A=8.07131,B=1730.63,C=233.426;
  var logP=A - B/(C+T);
  var mmHg=Math.pow(10,logP);
  var kPa=mmHg/7.50062;
  return {c:T, mmHg:Math.round(mmHg*100)/100, kPa:Math.round(kPa*1000)/1000, note:'Antoine 方程（水，约 1–100°C 较准）'};
}
var EXPORTS={vaporPressure:vaporPressure};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.VaporPressureForgePure = EXPORTS; }
